mapper.select:
SELECT po.purchase_id, po.purchase_no, s.supplier_name, w.warehouse_name, u.nickname AS purchase_by_name, po.expect_date, po.total_qty, po.delivered_qty, po.unreceived_qty, po.returned_qty, po.subtotal, po.tax_amount, po.freight, po.other_amount, po.total_amount, po.status, CASE po.status WHEN 0 THEN '草稿' WHEN 1 THEN '已提交' WHEN 2 THEN '已审核' WHEN 3 THEN '部分到货' WHEN 4 THEN '已完成' WHEN 5 THEN '已作废' ELSE '未知' END AS status_text, po.audit_time FROM wms_purchase_order po LEFT JOIN wms_supplier s ON po.supplier_id = s.supplier_id LEFT JOIN wms_warehouse w ON po.warehouse_id = w.warehouse_id LEFT JOIN sys_user u ON po.purchase_by = u.user_id
po.deleted = 0
AND po.purchase_no LIKE CONCAT('%', #{req.purchaseNo}, '%')
AND po.supplier_id = #{req.supplierId}
AND po.warehouse_id = #{req.warehouseId}
AND po.status = #{req.status}
AND po.purchase_by = #{req.purchaseBy}
AND po.create_time >= #{req.dateRangeStart}
AND po.create_time <= #{req.dateRangeEnd}
ORDER BY po.create_time DESC
